"""Streamlit dashboard for aggregate VITALIS evaluation JSON; no patient records."""

from __future__ import annotations

import json

import pandas as pd
import streamlit as st

st.set_page_config(page_title="VITALIS Research Dashboard", page_icon="🩺", layout="wide")
st.title("VITALIS · Research Evaluation")
st.warning("Research prototype only. Not for diagnosis, triage, or treatment decisions.")
st.write(
    "Upload an aggregate metrics JSON generated by scripts/train_baseline.py. "
    "Do not upload patient-level records or predictions."
)

uploaded = st.file_uploader("Aggregate metrics JSON", type=["json"])
if uploaded is None:
    st.info("No report loaded. Run the training script locally and upload its aggregate JSON output.")
    st.code(
        "python scripts/train_baseline.py /path/to/local_psv_data "
        "--output outputs/baseline_metrics.json"
    )
    st.stop()

try:
    report = json.load(uploaded)
except (json.JSONDecodeError, UnicodeDecodeError) as exc:
    st.error(f"Could not parse JSON: {exc}")
    st.stop()

if not isinstance(report, dict) or "test_metrics" not in report or "patient_counts" not in report:
    st.error("This does not look like a VITALIS aggregate evaluation report.")
    st.stop()

st.subheader("Experiment")
st.write({k: report.get(k) for k in ("model", "feature_mode", "seed", "threshold_selection")})
counts = report["patient_counts"]
metrics = report["test_metrics"]
cols = st.columns(4)
for col, label, value in zip(
    cols,
    ["Test patients", "Test rows", "AUROC", "AUPRC"],
    [counts.get("test"), metrics.get("rows"), metrics.get("auroc"), metrics.get("auprc")],
):
    col.metric(label, "—" if value is None else (f"{value:.3f}" if isinstance(value, float) else str(value)))

st.subheader("Alert burden against challenge-label windows")
alert_metrics = report.get("test_alert_burden")
if alert_metrics:
    st.json(alert_metrics)
else:
    st.info("This report predates alert-burden evaluation.")

st.subheader("Test-set metrics")
metric_names = ["auroc", "auprc", "brier_score", "sensitivity", "specificity", "ppv", "npv"]
metric_frame = pd.DataFrame(
    [{"metric": name, "value": metrics.get(name)} for name in metric_names if metrics.get(name) is not None]
)
st.dataframe(metric_frame, use_container_width=True, hide_index=True)
if not metric_frame.empty:
    st.bar_chart(metric_frame.set_index("metric"))
st.subheader("Confusion matrix at the stated threshold")
st.json(metrics.get("confusion_matrix", {}))
st.subheader("Limitations")
for limitation in report.get("limitations", []):
    st.write(f"- {limitation}")
st.caption("Metrics are retrospective research summaries. They do not establish clinical utility or safety.")
